/**
 * The dbt fixture on both storages, for tests that run the dbt loop (Physical,
 * Compare, Sync, Draw / Add from dbt, selectors) over YAML/JSON and native
 * DBML alike:
 *
 *   describe.each(DBT_FIXTURES)('%s storage', (storage, fixture) => { … })
 *
 * `dbt-project` keeps its logical model as `logical-models/*.yml` plus
 * `<layer>/<diagram>.json`; `dbt-project-dbml` is its Convert (generated by
 * `npm run regen:dbt-dbml-fixture`, pinned by `dbtProjectDbmlFixture.test.ts`):
 * `<layer>/tables/<schema>/<table>.dbml`, `<layer>/relationships/<layer>.dbml`
 * and `<layer>/diagrams/<diagram>.dbml`. The helpers below map one name to
 * the file that holds it on either storage, so a test names `showcase` or
 * `dim_customer` once.
 */
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

export type DbtStorage = 'yaml' | 'dbml';

export const FIXTURES_DIR = path.resolve(__dirname, '../../fixtures');
export const SEMANTIC_DIR = '.erd-studio';

/** `[storage, fixture folder]`, for `describe.each`. */
export const DBT_FIXTURES: ReadonlyArray<readonly [DbtStorage, string]> = [
  ['yaml', 'dbt-project'],
  ['dbml', 'dbt-project-dbml'],
] as const;

export function dbtFixtureRoot(fixture: string): string {
  return path.join(FIXTURES_DIR, fixture);
}

/** A diagram's path relative to the semantic dir: `silver/showcase.json` or `silver/diagrams/showcase.dbml`. */
export function diagramRel(storage: DbtStorage, layer: string, name: string): string {
  return storage === 'yaml' ? `${layer}/${name}.json` : `${layer}/diagrams/${name}.dbml`;
}

/** A diagram's absolute path under `root`. */
export function diagramPath(root: string, storage: DbtStorage, layer: string, name: string): string {
  return path.join(root, SEMANTIC_DIR, ...diagramRel(storage, layer, name).split('/'));
}

/**
 * The file that holds a table under `root`: `logical-models/<name>.yml` (or a
 * layer folder below it) on YAML, `<layer>/tables/<schema>/<name>.dbml` on
 * DBML. Found by listing (names compare case-insensitively), so it follows
 * whatever Convert chose; undefined when no file holds it.
 */
export function tableFilePath(root: string, storage: DbtStorage, name: string): string | undefined {
  const erd = path.join(root, SEMANTIC_DIR);
  const want = `${name.toLowerCase()}.${storage === 'yaml' ? 'yml' : 'dbml'}`;
  const hits: string[] = [];
  const walk = (dir: string, inTables: boolean): void => {
    if (!fs.existsSync(dir)) return;
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const abs = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(abs, inTables || entry.name === 'tables' || entry.name === 'logical-models');
      } else if (inTables && entry.name.toLowerCase() === want) {
        hits.push(abs);
      }
    }
  };
  walk(erd, false);
  if (hits.length > 1) throw new Error(`${name}: more than one table file (${hits.join(', ')})`);
  return hits[0];
}

/** The DBML layer's relationships file (`<layer>/relationships/<layer>.dbml`); undefined on YAML, where they live in the many side's yml. */
export function relationshipsPath(root: string, storage: DbtStorage, layer: string): string | undefined {
  return storage === 'yaml' ? undefined : path.join(root, SEMANTIC_DIR, layer, 'relationships', `${layer}.dbml`);
}

/**
 * A temp copy of a fixture. Timestamps are kept: manifest staleness compares
 * the manifest's mtime with the model files', and a plain copy reads stale.
 */
export function copyDbtFixture(fixture: string, prefix = 'erd-dbt-fixture'): string {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), `${prefix}-${fixture}-`));
  fs.cpSync(dbtFixtureRoot(fixture), root, { recursive: true, preserveTimestamps: true });
  return root;
}

/** Path relative to the semantic dir, `/`-separated. */
export function semanticRel(root: string, abs: string): string {
  return path.relative(path.join(root, SEMANTIC_DIR), abs).split(path.sep).join('/');
}

/**
 * Sets a diagram's `stubColumns`: the JSON key on YAML, the Project's
 * `erd_stub_columns` (a JSON array in one string) on DBML.
 */
export function setStubColumns(file: string, storage: DbtStorage, names: string[]): void {
  const text = fs.readFileSync(file, 'utf-8');
  if (storage === 'yaml') {
    const json = JSON.parse(text);
    json.stubColumns = names;
    fs.writeFileSync(file, JSON.stringify(json, null, 2));
    return;
  }
  const line = `  erd_stub_columns: '${JSON.stringify(names)}'`;
  const next = text.replace(/(Project\s+[^{\n]+\{\n)/, `$1${line}\n`);
  if (next === text) throw new Error(`${file}: no Project block to add erd_stub_columns to`);
  fs.writeFileSync(file, next);
}
